import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"CoreLib Actions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/level/corelib-actions.md","filePath":"en/modules/level/corelib-actions.md","lastUpdated":0}`),a={name:`en/modules/level/corelib-actions.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="corelib-actions" tabindex="-1">CoreLib Actions <a class="header-anchor" href="#corelib-actions" aria-label="Permalink to “CoreLib Actions”">​</a></h1><p>When EmakiLevel is enabled, it adds level and experience operation stages to the CoreLib action registry. They can be used by other module action lists, such as cooking completion, forge results, strengthen stages, skill rewards, or CoreLib pipeline templates.</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>This page documents only the stages registered by EmakiLevel. CoreLib built-in stages are documented in <a href="./../corelib/actions.html">CoreLib Actions</a>. Current stage IDs use only the canonical names below; historical aliases are no longer registered. The old <code>emakileveladdexp</code> is now written <code>level_add_exp</code>, the others follow the same rule, and the old <code>emakilevellevelup</code> is now <code>level_up</code>.</p></div><h2 id="stage-ids" tabindex="-1">Stage IDs <a class="header-anchor" href="#stage-ids" aria-label="Permalink to “Stage IDs”">​</a></h2><p>All eight stages declare <code>REQUIRED_ENTITY</code>, and non-player targets are skipped.</p><table tabindex="0"><thead><tr><th>Stage ID</th><th>Operation</th><th>Uses <code>amount</code></th></tr></thead><tbody><tr><td><code>level_add_exp</code></td><td>Add exp</td><td>Yes</td></tr><tr><td><code>level_set_exp</code></td><td>Set exp</td><td>Yes</td></tr><tr><td><code>level_remove_exp</code></td><td>Remove exp</td><td>Yes</td></tr><tr><td><code>level_add_level</code></td><td>Add levels</td><td>Yes</td></tr><tr><td><code>level_set_level</code></td><td>Set levels</td><td>Yes</td></tr><tr><td><code>level_remove_level</code></td><td>Remove levels</td><td>Yes</td></tr><tr><td><code>level_reset</code></td><td>Reset one level type</td><td>No</td></tr><tr><td><code>level_up</code></td><td>Manually level up one type</td><td>No</td></tr></tbody></table><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h2><p>All eight stages accept these parameters:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Level type ID, such as <code>main</code>, <code>combat</code>, or <code>mining</code>.</td></tr><tr><td><code>amount</code></td><td>EXPRESSION</td><td>No</td><td><code>0</code></td><td>Experience or level amount. Plain numbers and CoreLib expressions are accepted. Level operations round this value to an integer.</td></tr><tr><td><code>reason</code></td><td>STRING</td><td>No</td><td><code>action</code></td><td>Audit reason passed to the level service.</td></tr></tbody></table><p><code>level_add_exp</code> accepts two more:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>auto_upgrade</code></td><td>BOOLEAN</td><td>No</td><td><code>true</code></td><td>Whether to level up automatically when the threshold is crossed.</td></tr><tr><td><code>silent</code></td><td>BOOLEAN</td><td>No</td><td><code>false</code></td><td>Whether to suppress the level-up feedback.</td></tr></tbody></table><p><code>level_reset</code> and <code>level_up</code> ignore the value of <code>amount</code>, but still declare the parameter, so passing it is not reported as an unknown argument. <code>auto_upgrade</code> and <code>silent</code> are declared only on <code>level_add_exp</code>; writing them on another stage is an unknown-argument error at load time.</p><p>Which player is affected comes from the source, so there is no <code>target</code> parameter any more: use <code>self</code> for the caster, or <code>player_by_name</code> for a named player.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Add 50 main exp to yourself</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | level_add_exp type=main amount=50 reason=forge_reward&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Add 1 combat level to yourself</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | level_add_level type=combat amount=1 reason=boss_reward&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Add exp without auto level-up and without feedback</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | level_add_exp type=main amount=10 auto_upgrade=false silent=true&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Set mining exp for a named player</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | level_set_exp type=mining amount=200 reason=admin_adjust&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Reset the main level type</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | level_reset type=main reason=admin_reset&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Run one manual level-up through the level system</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | level_up type=main&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # amount as an expression</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | level_add_exp type=main amount=%var.base%*2+10&#39;</span></span></code></pre></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li><code>amount</code> is declared as EXPRESSION. Placeholders in the argument text are rendered before the expression is evaluated, so <code>%var.*%</code>, context placeholders written by the calling module, and PlaceholderAPI placeholders can all take part in the arithmetic.</li><li>Level operations (<code>level_add_level</code>, <code>level_set_level</code>, <code>level_remove_level</code>) round <code>amount</code> to an integer.</li><li>When the level service declines the operation, the stage fails with <code>REJECTED</code> and reports the service&#39;s reason.</li><li>On success the stage reports <code>type</code>, <code>old_level</code>, <code>new_level</code>, <code>old_exp</code>, <code>new_exp</code>, and <code>amount</code>, so the debug output shows the state before and after.</li></ul>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};